const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var canada = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Canada'));

  var startDate = '2023-10-24';
  var endDate = '2023-10-25';

  // 2. Data Acquisition - VIIRS Active Fires
  var fires = ee.ImageCollection('NOAA/VIIRS/001/VNP14IMGML1')
    .filterDate(startDate, endDate)
    .filterBounds(canada);

  var fireCount = fires.size().getInfo();
  console.log(`Fire detection images: ${fireCount}`);

  if (fireCount === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Count fire pixels
  var fireImage = fires.first();

  // FireMask values: 7,8,9 = high confidence fires
  var firePixels = fireImage.select('FireMask')
    .gt(6); // Values 7,8,9 are high confidence fires

  var stats = firePixels.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: canada,
    scale: 1000,
    maxPixels: 1e9
  });

  var fireCount = stats.get('FireMask').getInfo();
  console.log(`Active fire pixels: ${fireCount}`);

  // 4. Validation & Final Answer
  if (fireCount === null || fireCount === undefined || isNaN(fireCount)) {
    console.log("<answer>C3</answer>");
  } else if (fireCount > 0) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
